seq = ''.join(open('region.fasta').read().split('\n')[1:]).upper()
n=len(seq)
MIN=25
hits=[]
# find maximal exact repeats (both copies), length>=MIN, via comparing positions
i=0
seen=set()
while i<n-MIN:
    # for each i find longest match j>i
    best=0; bestj=None
    for j in range(i+1,n-MIN+1):
        L=0
        while j+L<n and seq[i+L]==seq[j+L]:
            L+=1
        if L>best:
            best=L; bestj=j
    if best>=MIN:
        hits.append((i+1,bestj+1,best))
        i+=1  # step
    else:
        i+=1
# consolidate overlapping hits: keep only maximal ones (not contained in a longer)
hits.sort(key=lambda x:-x[2])
kept=[]
for h in hits:
    a,b,L=h
    contain=False
    for (a2,b2,L2) in kept:
        # h contained if same relative offset and within
        if (b2-a2)==(b-a) and a2<=a and b<=b2:
            contain=True;break
    if not contain:
        kept.append(h)
for h in kept[:20]:
    print(f"repeat: pos {h[0]} and {h[1]}, length {h[2]}")

seq = ''.join(open('region.fasta').read().split('\n')[1:]).upper()
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

# GC by windows and repeat region
def gc(s): 
    s=[x for x in s if x in 'ACGT']
    return 100*sum(x in 'GC' for x in s)/len(s)
print("GC whole:", round(gc(seq),1))
print("GC 1-1696:", round(gc(seq[:1696]),1))
print("GC 1697-2280 (repeat array):", round(gc(seq[1696:2280]),1))
print("GC 2281-3000:", round(gc(seq[2280:]),1))

# Inverted repeats: find palindromes >= 14 bp
n=len(seq)
found=[]
for i in range(n):
    for j in range(i+14, min(i+60, n)+1):
        sub=seq[i:j]
        if sub==rc(sub):
            found.append((i+1,j,len(sub)))
# non-overlapping maximal palindromes
kept=[]
for f in sorted(found,key=lambda x:-x[2]):
    if not any(k[0]<=f[0] and f[1]<=k[1] for k in kept):
        kept.append(f)
print("\nPalindromes (even, >=14bp):")
for k in kept[:15]:
    print(f"  {k[0]}-{k[1]} len {k[2]}: {seq[k[0]-1:k[1]]}")

